from typing import Dict, Optional, Any
from pydantic import BaseModel, Field
from devsecops_agent.schemas.exploit import ExecutionResult


class PatchProposal(BaseModel):
    """Output generated by Patcher Agent (Algorithm 3)."""
    candidate_id: str
    attempt: int = 1
    root_cause_analysis: str
    diff_patch: str
    modified_files: Dict[str, str] = Field(default_factory=dict, description="Relative file path -> full patched content")
    rationale: str = ""
    metadata: Dict[str, Any] = Field(default_factory=dict)


class PatchVerificationResult(BaseModel):
    """Result of running exploit re-test and regression test suite on patched code."""
    candidate_id: str
    attempt: int
    patch_applied: bool
    exploit_blocked: bool
    regression_passed: bool
    exploit_run_result: Optional[ExecutionResult] = None
    regression_run_result: Optional[ExecutionResult] = None
    summary: str = ""
